/* Fictional rival recordings, generated by node build.mjs from real public inputs.
   No run state, simulation speed or finished time is changed. All pilots refuse gifts
   and use the default seed/no stakes; their targets follow the selected difficulty.
   TRACE only uses required boost and cautious clears; PATCH sprints on alternate safe
   openings; MICA sprints on every safe opening while reserving 45 compute for hazards.
   For each course, deterministic reaction candidates remove failed/hit recordings:
   TRACE 300/250/200/150 ms; PATCH/MICA 0/50/100/150 ms. Keep TRACE's slowest clean
   route, MICA's fastest, and PATCH's clean route nearest the midpoint of those times.
   Only a <=300 ms gap permits a visible late launch: PATCH +250 ms, TRACE +900 ms.
   The runner is stationary during that beat, then follows the unscaled recording.
   Ties never earn medals. The ordinary 300 ms reference uses one short, safe opening
   boost on non-boss courses, and no optional boost in boss approaches.

   Wire format: courses[difficulty][stage][tier] = [timeMs, launchMs, reactionTicks, b64].
   timeMs includes launchMs, so each sector records whether separation is by habits or
   by late launch. Sample every 30 active ticks, including exact start/final samples.
   Each sample is distance delta (quarter metres, byte; 255 + uint16 for long deltas),
   x (signed 1/32 metre biased by 128), y (low 6 bits, 1/16 metre) + slide/boost bits.
   Last sample uses round((timeMs-launchMs)*60/1000), not a padded half-second.
   The build enforces <=60,000 UTF-8 bytes for the complete embedded object.
   CLI: node tools/rivals.cjs [--check] (timing/size report; --check verifies 300 ms).
*/
'use strict';
const Core=require('../src/benchmark-core.js'),drive=require('./route-check.cjs');
const SAMPLE_TICKS=30,MAX_BYTES=60000,DIFFICULTIES=['hard','expert','nightmare'];
const profiles=[{id:'trace',name:'TRACE-19',delays:[18,15,12,9]},{id:'patch',name:'PATCH-03',delays:[9,6,3,0]},{id:'mica',name:'MICA-02',delays:[0,3,6,9]}];
function reference(stage,difficulty='hard'){
 return drive(Core.SEED,difficulty,stage,{reactionTicks:18,gifts:'refuse',openingBoost:Core.levelFor(stage).boss?0:24});
}
function pack(trace){
 const replay=new Core.Run(trace.seed,trace.options),bytes=[];let cursor=0,lastD=0,lastTick=-1;
 const sample=()=>{
  const g=replay.state,tick=Math.round((g.time-g.levelStartTime)*60);if(tick===lastTick)return;
  const d=Math.round((g.distance-Core.stageStart(g.stage))*4),delta=d-lastD,x=Math.round(g.x*32)+128,y=Math.round(Math.max(0,g.y)*16);
  if(delta<0||delta>65535||x<0||x>255||y>63)throw Error('Rival sample is outside its lossless timing/compact position bounds');
  if(delta<255)bytes.push(delta);else bytes.push(255,delta&255,delta>>>8);
  bytes.push(x,y|(g.slide>0?64:0)|(g.boost?128:0));lastD=d;lastTick=tick;
 };
 sample();
 while(!replay.ended&&replay.ticks<trace.ticks){
  while(cursor<trace.inputs.length&&trace.inputs[cursor][0]===replay.ticks)replay.input(trace.inputs[cursor++][1]);
  replay.step();const tick=Math.round(replay.state.time*60);
  if(tick%SAMPLE_TICKS===0||replay.ended)sample();
 }
 if(!replay.won||replay.result().durationMs!==trace.result.durationMs)throw Error('Rival public-input replay did not reproduce its finish');
 return Buffer.from(bytes).toString('base64');
}
function candidates(stage,difficulty,profile){
 const rows=profile.delays.map(reactionTicks=>{
  const trace=drive(Core.SEED,difficulty,stage,{rival:profile.id,reactionTicks,gifts:'refuse'});
  return {trace,reactionTicks,timeMs:trace.result.durationMs};
 }).filter(r=>r.trace.result.won&&r.trace.result.hits===0);
 if(!rows.length)throw Error(`${difficulty} sector ${stage+1}: ${profile.name} has no clean public-input route`);
 return rows.sort((a,b)=>a.timeMs-b.timeMs||a.reactionTicks-b.reactionTicks);
}
function generate(){
 const data={version:Core.VERSION,seed:Core.SEED,step:SAMPLE_TICKS,courses:{}};
 for(const difficulty of DIFFICULTIES){
  const courses=[];data.courses[difficulty]=courses;
  for(let stage=0;stage<12;stage++){
   const trace=candidates(stage,difficulty,profiles[0]).at(-1),mica=candidates(stage,difficulty,profiles[2])[0],middle=(trace.timeMs+mica.timeMs)/2;
   const patch=candidates(stage,difficulty,profiles[1]).sort((a,b)=>Math.abs(a.timeMs-middle)-Math.abs(b.timeMs-middle)||a.reactionTicks-b.reactionTicks)[0];
   const launch=[0,0,0];
   if(Math.abs(patch.timeMs-mica.timeMs)<=300)launch[1]=250;
   if(Math.abs(trace.timeMs-(patch.timeMs+launch[1]))<=300)launch[0]=900;
   const rows=[trace,patch,mica].map((r,i)=>[r.timeMs+launch[i],launch[i],r.reactionTicks,pack(r.trace)]);
   if(!(rows[0][0]>rows[1][0]&&rows[1][0]>rows[2][0]))throw Error(`${difficulty} sector ${stage+1}: rival habits do not form strictly increasing skill`);
   courses.push(rows);
  }
 }
 const bytes=Buffer.byteLength(JSON.stringify(data));if(bytes>MAX_BYTES)throw Error(`Rival data is ${bytes} bytes; cap is ${MAX_BYTES}`);
 return data;
}
if(require.main===module){
 const data=generate(),check=process.argv.includes('--check');
 console.log('SECTOR  TRACE-19  PATCH-03  MICA-02  300ms  LAUNCH(T/P)');
 for(let stage=0;stage<12;stage++){
  const rivals=data.courses.hard[stage],run=reference(stage),r=run.result;
  console.log(`${String(stage+1).padStart(2,'0')}      ${rivals.map(x=>(x[0]/1000).toFixed(3)).join('    ')}    ${(r.durationMs/1000).toFixed(3)}    ${rivals[0][1]}/${rivals[1][1]}`);
  if(check&&(!r.won||r.hits||r.durationMs>=rivals[0][0]||r.durationMs<rivals[2][0]))throw Error(`Sector ${stage+1}: 300 ms must beat TRACE, not MICA, with a real clean run`);
 }
 console.log(`${Buffer.byteLength(JSON.stringify(data))} bytes / ${MAX_BYTES}; 108 replay-reproduced ghosts / ${Core.VERSION}`);
}
module.exports={generate,reference,profiles,SAMPLE_TICKS,MAX_BYTES};
